import * as T from './assets/three.module.js';
const canvas=document.querySelector('#world');let renderer;try{renderer=new T.WebGLRenderer({canvas,alpha:false,antialias:innerWidth>700,powerPreference:'high-performance'})}catch{document.body.classList.add('no-webgl');throw Error('WebGL unavailable')}
