const scene=new T.Scene();scene.background=new T.Color('#30221b');scene.fog=new T.FogExp2('#30221b',.025);const camera=new T.PerspectiveCamera(42,innerWidth/innerHeight,.1,180);camera.position.set(0,7,20);const amb=new T.HemisphereLight('#ffe1aa','#173d30',2.3);scene.add(amb);const sun=new T.DirectionalLight('#ffc783',3);sun.position.set(8,15,10);scene.add(sun);const spot=new T.PointLight('#ffbb56',60,30);spot.position.set(4,6,3);scene.add(spot);
const mat=(color,metalness=.2,roughness=.65)=>new T.MeshStandardMaterial({color,metalness,roughness});const gold=mat('#d7ac59',.7,.3),green=mat('#175846'),red=mat('#771e29'),sand=mat('#b78a57'),dark=mat('#172d29'),ivory=mat('#ead6a9');
function box(w,h,d,m,x=0,y=0,z=0){let o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);return o}function sphere(r,m,x=0,y=0,z=0){let o=new T.Mesh(new T.SphereGeometry(r,16,12),m);o.position.set(x,y,z);return o}function cyl(r1,r2,h,m,x=0,y=0,z=0){let o=new T.Mesh(new T.CylinderGeometry(r1,r2,h,24),m);o.position.set(x,y,z);return o}function ring(r,m){const o=new T.Mesh(new T.TorusGeometry(r,.035,6,100),m);o.rotation.x=-Math.PI/2;return o}
const roots=Array.from({length:7},()=>{const g=new T.Group();scene.add(g);return g});
function floor(g,color='#24392c'){let o=new T.Mesh(new T.PlaneGeometry(170,170),mat(color,0,.9));o.rotation.x=-Math.PI/2;o.position.y=-.04;g.add(o)}
function person(color='#943d35',dress=false){const g=new T.Group();g.add(sphere(.17,mat('#cf9a62'),0,1.44));g.add(cyl(.21,dress?.65:.32,.65,mat(color),0,.91));if(!dress){g.add(box(.15,.6,.16,dark,-.13,.3),box(.15,.6,.16,dark,.13,.3))}else g.add(cyl(.3,.73,.54,mat(color),0,.4));const arm=box(.65,.10,.12,gold,0,1.14,0);arm.rotation.z=.5;g.add(arm);g.add(sphere(.19,gold,0,1.56));return g}
function architecture(g,x,z,h=3){const b=new T.Group();b.position.set(x,0,z);b.add(box(2.8,h,2,sand,0,h/2),box(3,.17,2.3,gold,0,h+.1));for(let k=-1;k<=1;k++){b.add(box(.35,.8,.04,dark,k*.75,h*.55,1.03));b.add(sphere(.18,gold,k*.75,h*.55+.4,1.06))}b.add(cyl(1.1,1.4,.3,sand,0,h+.3),sphere(.85,sand,0,h+.55));g.add(b)}
// Arrival: stylised miniature city, train, traveller, opening luggage.
const arrival=roots[0];floor(arrival,'#766148');for(let i=0;i<12;i++)architecture(arrival,(i-6)*3.4,-10-(i%2)*2,3+(i%3)*.7);const train=new T.Group();for(let i=0;i<3;i++){train.add(box(6,2.1,2,green,i*6-10,1.5,-4));for(let k=0;k<5;k++)train.add(box(.65,.65,.05,gold,i*6-12+k,1.7,-2.98));for(const x of[-2,2])train.add(cyl(.4,.4,.25,dark,i*6-10+x,.5,-3));}arrival.add(train);const traveller=person('#dac291');traveller.position.set(4,0,2);traveller.scale.setScalar(1.6);arrival.add(traveller);const luggage=new T.Group();luggage.position.set(5.2,0,2);luggage.add(box(.8,.8,.4,red,0,.5));const lid=box(.8,.8,.09,gold,0,.5,.24);luggage.add(lid);arrival.add(luggage);const sticks=box(.08,.7,.08,gold,0,.7,0);sticks.rotation.z=.4;luggage.add(sticks);
// Markets: illuminated awnings and a continuous street of layered stalls.
const market=roots[1];floor(market,'#23362d');const marketLights=[];for(let i=0;i<10;i++){const x=(i%5-2)*4,z=i<5?-3:-10;architecture(market,x,z,2.5+(i%2)*.5);const awning=box(3,.15,2, i%2?red:green,x,2.4,z+1.7);awning.rotation.x=.1;market.add(awning);for(let k=0;k<3;k++)market.add(box(.6,1.2,.08,[gold,red,green][k],x+(k-1)*.8,1.6,z+1.2));const light=sphere(.12,new T.MeshBasicMaterial({color:'#9b6d35'}),x,3.4,z+1.5);market.add(light);marketLights.push(light)}for(let i=0;i<24;i++){let x=-11+i;const light=sphere(.065,new T.MeshBasicMaterial({color:'#f3c86e'}),x,5-Math.sin(i/24*Math.PI),0);market.add(light)}
// River drive: bridge geometry, skyline and a steerable car.
const drive=roots[2];floor(drive,'#102b2c');drive.add(box(7,.08,130,mat('#292c2c'),3,0,0));const marks=[];for(let i=0;i<35;i++){const m=box(.1,.015,1.5,gold,3,.06,-i*4+35);drive.add(m);marks.push(m)}for(let i=0;i<16;i++){const x=i%2?-2:8,z=(i>>1)*8-32;drive.add(cyl(.06,.08,5,gold,x,2.5,z),sphere(.2,new T.MeshBasicMaterial({color:'#ffe3a0'}),x,5,z));}for(let i=0;i<8;i++)architecture(drive,-8-i%2*4,i*6-25,2+i%3);const bridge=new T.Group();bridge.position.set(0,0,-22);bridge.add(box(28,.5,3,sand,0,1.8));for(let i=-6;i<=6;i++){const p=box(.12,8,.12,[gold,red,green][Math.abs(i)%3],i*1.6,5);p.rotation.z=i*.08;bridge.add(p)}drive.add(bridge);const car=new T.Group();car.add(box(2,.6,3.8,red,0,.7),box(1.75,.7,1.8,green,0,1.3,-.2),box(1.55,.5,.05,new T.MeshStandardMaterial({color:'#a7c8b5',metalness:.7,roughness:.1}),0,1.3,.74));const wheels=[];for(const x of[-1,1])for(const z of[-1.2,1.2]){let wheel=cyl(.4,.4,.22,dark,x,.42,z);wheel.rotation.z=Math.PI/2;car.add(wheel);wheels.push(wheel)}for(const x of[-.7,.7])car.add(box(.35,.2,.06,new T.MeshBasicMaterial({color:'#fff1c4'}),x,.8,1.93));car.position.set(3,0,4);drive.add(car);
function circle(g,count=32,r=5){const people=[];for(let i=0;i<count;i++){const a=i/count*Math.PI*2;const p=person(['#a63342','#ce9e45','#1d7858','#ca6241'][i%4],i%2===0);p.position.set(Math.sin(a)*r,0,Math.cos(a)*r);p.rotation.y=a+Math.PI/2;g.add(p);people.push(p)}for(let r0 of[r-.8,r+.8]){let o=ring(r0,gold);o.position.y=.02;g.add(o)}return people}
const heritage=roots[3];floor(heritage,'#13372c');const heritageRing=new T.Group();heritageRing.position.x=4;heritage.add(heritageRing);circle(heritageRing,28,5);const pot=cyl(.6,.9,1.3,red,0,.65);heritageRing.add(pot,sphere(.3,new T.MeshBasicMaterial({color:'#ffc660'}),0,1.4));
// Aarti: brass thali, supplied diya art, and reactive warm light.
const devotion=roots[4];floor(devotion,'#0a211d');const thali=new T.Group();thali.position.set(4,.5,0);devotion.add(thali);thali.add(cyl(3,2.8,.14,gold),ring(2.8,gold));const flames=[];for(let i=0;i<7;i++){const a=i/7*Math.PI*2,x=Math.cos(a)*2,z=Math.sin(a)*2;thali.add(cyl(.28,.14,.22,red,x,.18,z));const flame=sphere(.15,new T.MeshBasicMaterial({color:'#ffd681'}),x,.49,z);flame.scale.y=2.2;thali.add(flame);flames.push(flame)}const tex=new T.TextureLoader().load('assets/diya.webp');tex.colorSpace=T.SRGBColorSpace;const diyaArt=new T.Mesh(new T.PlaneGeometry(6,4),new T.MeshBasicMaterial({map:tex,transparent:true,blending:T.AdditiveBlending,depthWrite:false}));diyaArt.position.set(4,4,-4);devotion.add(diyaArt);
const celebration=roots[5];floor(celebration,'#213228');const dancers=new T.Group();dancers.position.x=3;celebration.add(dancers);circle(dancers,44,7);circle(dancers,28,4.6);circle(dancers,16,2.5);dancers.add(cyl(.7,1,1.6,gold,0,.8));const extraDancers=[];for(let i=0;i<12;i++){let p=person('#df5d70',true),a=i/12*Math.PI*2;p.position.set(Math.cos(a)*9,0,Math.sin(a)*9);p.visible=false;dancers.add(p);extraDancers.push(p)}
const stage=roots[6];floor(stage,'#10251e');stage.add(box(12,1,6,dark,3,.5,-3),box(13,7,.3,red,3,4,-6));const logoTex=new T.TextureLoader().load('assets/logo.webp');logoTex.colorSpace=T.SRGBColorSpace;const logo=new T.Mesh(new T.PlaneGeometry(6,4.1),new T.MeshBasicMaterial({map:logoTex,transparent:true}));logo.position.set(3,4.5,-5.8);stage.add(logo);const microphone=new T.Group();microphone.add(cyl(.04,.07,2.4,gold,0,1.2),sphere(.15,dark,0,2.45),cyl(.3,.3,.08,dark,0,.02));microphone.position.set(3,1,-1);stage.add(microphone);const beams=[];for(let i=0;i<5;i++){const b=new T.Mesh(new T.ConeGeometry(2,12,24,1,true),new T.MeshBasicMaterial({color:'#eec571',transparent:true,opacity:.07,side:T.DoubleSide,depthWrite:false,blending:T.AdditiveBlending}));b.position.set((i-2)*3+3,6,-1);b.rotation.z=(i-2)*.16;stage.add(b);beams.push(b)}for(let i=0;i<32;i++){let p=person(i%2?'#654b32':'#6c3236',i%3===0);p.position.set((i%8-3)*1.6,0,4+Math.floor(i/8)*1.3);stage.add(p)}
const particlesGeometry=new T.BufferGeometry();const positions=new Float32Array(450*3);for(let i=0;i<450;i++){positions[i*3]=(Math.random()-.5)*45;positions[i*3+1]=Math.random()*16;positions[i*3+2]=(Math.random()-.5)*40}particlesGeometry.setAttribute('position',new T.BufferAttribute(positions,3));const particles=new T.Points(particlesGeometry,new T.PointsMaterial({color:'#ebbf69',size:.055,transparent:true,opacity:.55}));scene.add(particles);
const palettes=['#51402b','#232c23','#132a2b','#102e25','#061b16','#232119','#130c0c'];
// Dissolve adjacent worlds into one continuous camera view. Each scene keeps its
// own lighting and state, and both sides are derived from the same scroll value.
const bufferSize=new T.Vector2();renderer.getDrawingBufferSize(bufferSize);
const targets=[new T.WebGLRenderTarget(bufferSize.x,bufferSize.y),new T.WebGLRenderTarget(bufferSize.x,bufferSize.y)];
const compositeScene=new T.Scene(),compositeCamera=new T.Camera();
const compositeMaterial=new T.ShaderMaterial({uniforms:{a:{value:targets[0].texture},b:{value:targets[1].texture},blend:{value:0}},vertexShader:'varying vec2 vUv; void main(){vUv=uv;gl_Position=vec4(position.xy,0.0,1.0);}',fragmentShader:'uniform sampler2D a; uniform sampler2D b; uniform float blend; varying vec2 vUv; void main(){gl_FragColor=mix(texture2D(a,vUv),texture2D(b,vUv),blend);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}',depthTest:false,depthWrite:false});
compositeScene.add(new T.Mesh(new T.PlaneGeometry(2,2),compositeMaterial));
const limit=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
function cameraPose(n,orbit,mobile){
 if(n===2)return {position:new T.Vector3(12+Math.sin(orbit)*4,8,18),target:new T.Vector3(-1,1,-1)};
 if(n===5)return {position:new T.Vector3(3,16,22),target:new T.Vector3(-2,0,0)};
 return {position:new T.Vector3(Math.sin(orbit)*3,mobile?9:6.5,mobile?25:20),target:new T.Vector3(mobile?3:-1,mobile?3:1,0)};
}
function prepare(n,state,time,orbit){
 const p=limit(state.progress-n);roots.forEach((g,i)=>g.visible=i===n);
 scene.background.set(palettes[n]);scene.fog.color.copy(scene.background);spot.intensity=40;
 if(n===0){train.position.x=-p*6;lid.rotation.x=state.actions[0]?-1.4:0;sticks.visible=!!state.actions[0]}
 if(n===1){marketLights.forEach(l=>l.material.color.set(state.actions[1]?'#ffe18d':'#9b6d35'));market.rotation.y=orbit*.13}
 if(n===2){marks.forEach((m,i)=>m.position.z=((-i*4+p*50)%140)+35);car.position.x=3+Math.sin(orbit)*2;car.rotation.y=Math.sin(orbit)*.2;wheels.forEach(w=>w.rotation.x=p*45)}
 if(n===3)heritageRing.rotation.y=orbit+(state.reduced?0:p*2);
 if(n===4){thali.rotation.y=orbit;thali.rotation.z=Math.sin(orbit)*.1;flames.forEach((f,i)=>{f.visible=state.actions[4]>0;f.scale.y=2.2+(state.reduced?0:Math.sin(time*8+i)*.4+state.breath)});diyaArt.material.opacity=state.actions[4]?1:.28;spot.intensity=state.actions[4]?75:15}
 if(n===5){dancers.rotation.y=orbit+(state.reduced?0:p*4);extraDancers.forEach((d,i)=>d.visible=i<state.actions[5])}
 if(n===6)beams.forEach((b,i)=>{b.rotation.z=(i-2)*.15+Math.sin(time*.7+i)*.12;b.material.opacity=state.actions[6]?.15:.07});
}
function loop(t){
 requestAnimationFrame(loop);const state=window.garba;if(!state||!state.worldVisible||document.hidden)return;
 const n=Math.min(6,Math.floor(state.progress)),next=Math.min(6,n+1),p=state.progress-n;
 let blend=next===n?0:limit((p-.65)/.35);blend=blend*blend*(3-2*blend);
 const time=state.reduced?0:t*.001,orbit=state.orbit+state.tiltX*.25+(state.reduced?0:state.progress*.12),mobile=innerWidth<650;
 const from=cameraPose(n,orbit,mobile),to=cameraPose(next,orbit,mobile);
 if(state.reduced){camera.position.set(0,mobile?10:8,mobile?27:23);camera.lookAt(2,1,0)}else{camera.position.copy(from.position).lerp(to.position,blend);camera.lookAt(from.target.lerp(to.target,blend));}camera.zoom=state.zoom;camera.updateProjectionMatrix();particles.rotation.y=state.reduced?0:time*.013;
 prepare(n,state,time,orbit);renderer.setRenderTarget(targets[0]);renderer.render(scene,camera);
 if(blend>0){prepare(next,state,time,orbit);renderer.setRenderTarget(targets[1]);renderer.render(scene,camera)}
 compositeMaterial.uniforms.blend.value=blend;renderer.setRenderTarget(null);renderer.render(compositeScene,compositeCamera);
 // Exposed only for deterministic forward/reverse transition verification.
 state.renderBlend={from:n,to:next,amount:blend};
}
requestAnimationFrame(loop);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.getDrawingBufferSize(bufferSize);targets.forEach(target=>target.setSize(bufferSize.x,bufferSize.y))});
